-- Ejecuta este archivo en Supabase > SQL Editor.
create table if not exists public.products (
  id text primary key,
  category text not null,
  name text not null,
  description text not null default '',
  price integer null check (price is null or price >= 0),
  active boolean not null default true,
  sort_order integer not null default 0,
  updated_at timestamptz not null default now()
);

create table if not exists public.admin_users (
  id uuid primary key references auth.users(id) on delete cascade
);

alter table public.products enable row level security;
alter table public.admin_users enable row level security;

-- Permisos SQL; las políticas RLS de abajo limitan qué filas puede consultar/modificar cada rol.
grant select on public.products to anon, authenticated;
grant update on public.products to authenticated;
grant select on public.admin_users to authenticated;

drop policy if exists "Anyone can read active products" on public.products;
create policy "Anyone can read active products" on public.products
  for select to anon, authenticated using (active = true);

drop policy if exists "Admins can read all products" on public.products;
create policy "Admins can read all products" on public.products
  for select to authenticated using (
    exists (select 1 from public.admin_users au where au.id = (select auth.uid()))
  );

drop policy if exists "Admins can update products" on public.products;
create policy "Admins can update products" on public.products
  for update to authenticated using (
    exists (select 1 from public.admin_users au where au.id = (select auth.uid()))
  ) with check (
    exists (select 1 from public.admin_users au where au.id = (select auth.uid()))
  );

drop policy if exists "Admins can read own admin record" on public.admin_users;
create policy "Admins can read own admin record" on public.admin_users
  for select to authenticated using (id = (select auth.uid()));

